PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;
CREATE TABLE tenants (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, line_channel_token_secret TEXT, liff_id TEXT, liff_url TEXT, store_display_name TEXT, timezone TEXT DEFAULT 'Asia/Taipei', message_templates TEXT);
CREATE TABLE tenant_config (
    tenant_id TEXT PRIMARY KEY,
    
    line_channel_token TEXT,          
    line_channel_secret TEXT,         
    liff_id TEXT,
    liff_url TEXT,
    
    groq_api_key TEXT,
    groq_model TEXT DEFAULT 'llama-3.1-8b-instant',
    openrouter_api_key TEXT,
    openrouter_model TEXT DEFAULT 'google/gemini-2.5-flash:free',
    
    brand_name TEXT NOT NULL,         
    brand_color TEXT DEFAULT '#00b900',
    store_address TEXT,
    
    operating_hours TEXT,             
    delivery_policy TEXT,             
    quick_replies TEXT,               
    flex_template TEXT,               
    default_password TEXT DEFAULT '12345678',
    locale TEXT DEFAULT 'zh-TW',      
    
    google_sheets_url TEXT,
    
    is_active INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, allow_scheduled_pickup INTEGER DEFAULT 1, store_status TEXT DEFAULT 'open', logo_url TEXT, announcement TEXT DEFAULT NULL, allow_dine_in INTEGER DEFAULT 1, features TEXT DEFAULT '[]', order_prefix TEXT DEFAULT NULL, latitude REAL, longitude REAL, cuisine_type TEXT DEFAULT 'vietnamese', is_marketplace_visible INTEGER DEFAULT 1, ai_order_redirect_enabled INTEGER NOT NULL DEFAULT 1, staff_ordering_enabled INTEGER NOT NULL DEFAULT 0,
    FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);
CREATE TABLE menu_categories (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    name TEXT NOT NULL,
    slug TEXT NOT NULL, 
    sort_order INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP, category_type TEXT DEFAULT 'catalog', selection_type TEXT DEFAULT 'single', is_required INTEGER DEFAULT 0, min_selection INTEGER DEFAULT 0, max_selection INTEGER DEFAULT 1, allow_customization INTEGER DEFAULT 1, applied_modifiers TEXT DEFAULT NULL, short_name TEXT, pricing_rules TEXT,
    FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
    UNIQUE(tenant_id, slug)
);
CREATE TABLE menu_items (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    category_id TEXT NOT NULL,
    name TEXT NOT NULL,
    price REAL NOT NULL CHECK(price >= 0),
    description TEXT,
    out_of_stock_until DATETIME, 
    sort_order INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, badge_text TEXT DEFAULT NULL, is_recommended INTEGER DEFAULT 0, item_type TEXT DEFAULT 'standard', max_per_order INTEGER DEFAULT NULL,
    FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
    FOREIGN KEY (category_id) REFERENCES menu_categories(id) ON DELETE RESTRICT
);
CREATE TABLE menu_customizations (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, key TEXT NOT NULL, title TEXT NOT NULL, type TEXT NOT NULL, sort_order INTEGER NOT NULL, options_json TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, is_required INTEGER DEFAULT 0);
CREATE TABLE menu_customization_option_rules (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    customization_key TEXT NOT NULL,
    option_id TEXT NOT NULL,
    rule_type TEXT NOT NULL DEFAULT 'min_order_subtotal',
    min_order_subtotal REAL NOT NULL CHECK (min_order_subtotal >= 0),
    threshold_basis TEXT NOT NULL DEFAULT 'merchandise_subtotal_after_pricing',
    error_message TEXT,
    is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (tenant_id, customization_key, option_id, rule_type)
);
CREATE TABLE modifier_groups (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    name TEXT NOT NULL,
    selection_type TEXT NOT NULL DEFAULT 'single', 
    is_required INTEGER NOT NULL DEFAULT 0,        
    min_selection INTEGER NOT NULL DEFAULT 0,
    max_selection INTEGER NOT NULL DEFAULT 1,
    sort_order INTEGER NOT NULL DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, scope TEXT DEFAULT 'item');
CREATE TABLE modifier_options (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    group_id TEXT NOT NULL REFERENCES modifier_groups(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    price INTEGER NOT NULL DEFAULT 0,              
    is_default INTEGER NOT NULL DEFAULT 0,
    sort_order INTEGER NOT NULL DEFAULT 0,
    out_of_stock_until DATETIME DEFAULT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE category_modifier_links (
    tenant_id TEXT NOT NULL,
    category_id TEXT NOT NULL REFERENCES menu_categories(id) ON DELETE CASCADE,
    group_id TEXT NOT NULL REFERENCES modifier_groups(id) ON DELETE CASCADE,
    sort_order INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (tenant_id, category_id, group_id)
);
CREATE TABLE item_modifier_links (
    tenant_id TEXT NOT NULL,
    item_id TEXT NOT NULL REFERENCES menu_items(id) ON DELETE CASCADE,
    group_id TEXT NOT NULL REFERENCES modifier_groups(id) ON DELETE CASCADE,
    sort_order INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (tenant_id, item_id, group_id)
);
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
